/**
 * @file Deterministic annotation reference numbering.
 * @description Preserves unique valid numbers and assigns conflicts in a stable
 * date, page, and identifier order without mutating annotations.
 */
import type { Annotation } from './annotation';
/** Returns whether a value is a positive safe annotation reference number. */
export declare function isValidReferenceNumber(value: unknown): value is number;
/** Compares annotations using valid date, page, and identifier ordering. */
export declare function compareAnnotationsForNumbering(left: Annotation, right: Annotation): number;
/** Returns the greatest valid reference number in an annotation iterable. */
export declare function getGreatestReferenceNumber(annotations: Iterable<Annotation>): number;
/** Normalizes missing, invalid, and duplicate numbers deterministically. */
export declare function normalizeAnnotationReferenceNumbers(annotations: readonly Annotation[]): Annotation[];
/** Assigns a unique number to a newly created annotation. */
export declare function assignAnnotationReferenceNumber(annotation: Annotation, existingAnnotations: Iterable<Annotation>, nextReferenceNumber?: number): Annotation;
